CREATE TABLE destination_entries (
 id TEXT PRIMARY KEY,
 province_id INTEGER NOT NULL CHECK(province_id BETWEEN 1 AND 34),
 kind TEXT NOT NULL CHECK(kind IN ('attractions','specialties')),
 name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),
 description TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '',
 version INTEGER NOT NULL DEFAULT 1,
 UNIQUE(province_id,kind,name)
);
